/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 * }
 */
// 遞迴：每往下一層就把目標值扣掉節點值，到葉子時檢查是否剛好為 0
// 時間複雜度: O(n)，空間複雜度: O(h)
function hasPathSum(root, targetSum) {
    if (!root)
        return false;
    const remain = targetSum - root.val;
    if (!root.left && !root.right)
        return remain === 0;
    return hasPathSum(root.left, remain) || hasPathSum(root.right, remain);
}

solutions.cpp:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
#include <stack>
using namespace std;

class Solution {
public:
    bool hasPathSum(TreeNode* root, int targetSum) {
        if (!root) return false;

        // 葉子節點
        if (!root->left && !root->right) {
            return targetSum == root->val;
        }

        // 遞迴檢查左右子樹
        return hasPathSum(root->left, targetSum - root->val) || 
               hasPathSum(root->right, targetSum - root->val);
    }

    // 迭代版本
    bool hasPathSum_v2(TreeNode* root, int targetSum) {
        if (!root) return false;

        stack<pair<TreeNode*, int>> stk;
        stk.push({root, targetSum});

        while (!stk.empty()) {
            auto [node, remaining] = stk.top();
            stk.pop();

            if (!node->left && !node->right) {
                if (remaining == node->val) return true;
            }

            if (node->right) 
                stk.push({node->right, remaining - node->val});
            if (node->left) 
                stk.push({node->left, remaining - node->val});
        }

        return false;
    }
};

